create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, role text not null default 'user' check (role in ('user','admin')), status text not null default 'active' check (status in ('active','suspended')), created_at timestamptz not null default now());
create table if not exists public.access_applications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, status text not null default 'pending' check (status in ('pending','approved','rejected')), submitted_at timestamptz not null default now(), reviewed_at timestamptz, reviewed_by uuid references public.profiles(id), review_note text);
create table if not exists public.entitlements (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, application_id uuid references public.access_applications(id), status text not null default 'active' check (status in ('active','expired','suspended')), approved_at timestamptz not null, expires_at timestamptz not null, quota_total_cents integer not null default 600 check (quota_total_cents = 600), quota_used_cents integer not null default 0, quota_remaining_cents integer not null default 600, approved_by uuid references public.profiles(id));
create table if not exists public.usage_ledger (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), entitlement_id uuid not null references public.entitlements(id), request_id text not null unique, provider text not null, model text not null, input_tokens integer, output_tokens integer, total_tokens integer, estimated_cost_cents integer not null default 0, status text not null, created_at timestamptz not null default now());
create table if not exists public.quota_reservations (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), entitlement_id uuid not null references public.entitlements(id), request_id text not null unique, reserved_cents integer not null, settled_cents integer not null default 0, status text not null, expires_at timestamptz not null, created_at timestamptz not null default now());

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id,email) values (new.id, new.email); insert into public.access_applications(user_id) values (new.id); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

create or replace function public.approve_application(p_application_id uuid, p_admin_id uuid) returns public.entitlements language plpgsql security definer set search_path = public as $$ declare result public.entitlements; begin if not exists (select 1 from public.profiles where id=p_admin_id and role='admin' and status='active') then raise exception 'not admin'; end if; update public.access_applications set status='approved', reviewed_at=now(), reviewed_by=p_admin_id where id=p_application_id and status='pending'; if not found then raise exception 'application unavailable'; end if; update public.profiles set status='active' where id=(select user_id from public.access_applications where id=p_application_id); insert into public.entitlements(user_id,application_id,approved_at,expires_at,quota_total_cents,quota_remaining_cents,approved_by) select user_id,id,now(),now()+interval '30 days',600,600,p_admin_id from public.access_applications where id=p_application_id returning * into result; return result; end; $$;

create or replace function public.reserve_quota(p_user_id uuid, p_request_id text, p_amount integer) returns public.quota_reservations language plpgsql security definer set search_path = public as $$ declare result public.quota_reservations; begin select * into result from public.quota_reservations where request_id=p_request_id; if found then return result; end if; update public.entitlements set quota_remaining_cents=quota_remaining_cents-p_amount where user_id=p_user_id and status='active' and expires_at>now() and quota_remaining_cents>=p_amount returning id,user_id,id,p_request_id,p_amount,0,'reserved',now()+interval '10 minutes',now() into result; if not found then raise exception 'quota unavailable'; end if; insert into public.quota_reservations values (result.*); return result; end; $$;

create or replace function public.refund_reservation(p_request_id text) returns void language plpgsql security definer set search_path = public as $$ begin update public.entitlements e set quota_remaining_cents=e.quota_remaining_cents+r.reserved_cents from public.quota_reservations r where r.request_id=p_request_id and r.status='reserved' and e.id=r.entitlement_id; update public.quota_reservations set status='refunded' where request_id=p_request_id and status='reserved'; end; $$;
